use vstd::prelude::*;

verus! {

    // Append a u64 element to the end of a Vec<u64>, without modifying the original.
    //
    // Specification:
    //   - The original vector `v` has length at most 100.
    //   - The returned vector `ret` has length exactly one more than `v`.
    //   - For all valid indices i < v.len(), ret[i] == v[i].
    //   - ret[v.len()] == elem.
    fn append(v: &Vec<u64>, elem: u64) -> Vec<u64>
        requires
            v.len() <= 100,
        ensures
            ret.len() == v.len() + 1,
        ensures
            forall |i: usize| i < v.len() ==> ret[i] == v[i],
        ensures
            ret[v.len()] == elem,
    {
        // We simply clone the original vector and push the new element.
        // Verus knows the specs of `clone` and `push`, so it can discharge
        // all the above post‐conditions automatically.
        let mut ret = v.clone();
        ret.push(elem);
        ret
    }

} // end of verus! block

